   (flags : list byte) (rpos rend wbase wfn bufp bsz mode lockv cookie : word) (J : fjunk),
  mem_inv rsegs m -> stk rsegs m lo (bv_unsigned sp) -> (lo + 64 <= bv_unsigned sp)%Z -> (bv_unsigned ra mod 2 = 0)%Z ->
  a0 = Z_to_bv 64 S -> a1 = Z_to_bv 64 l -> a2 = Z_to_bv 64 fa ->
  rw_cells rsegs m fa (fileC flags rpos rend (Z_to_bv 64 (B0 + cap)) (Z_to_bv 64 (B0 + k)) wbase wfn bufp bsz mode lockv (Z_to_bv 64 lbf) cookie J) ->
  (-2 ^ 31 <= lbf < 0)%Z ->
  u8arr rsegs m B0 ibuf -> Z.of_nat (length ibuf) = cap -> (0 <= k)%Z -> (0 <= l)%Z -> (k + l <= cap)%Z -> (0 < B0)%Z -> (B0 + cap < 2 ^ 63)%Z ->
  bytes_at rsegs m S sbs -> Z.of_nat (length sbs) = l -> (S + l < 2 ^ 63)%Z ->
  (S + l <= bv_unsigned sp - 64 \/ bv_unsigned sp <= S)%Z -> (S + l <= B0 + k \/ B0 + k + l <= S)%Z ->
  (fa + 232 <= bv_unsigned sp - 64 \/ bv_unsigned sp <= fa)%Z -> (B0 + cap <= bv_unsigned sp - 64 \/ bv_unsigned sp <= B0)%Z ->
  (B0 + cap <= fa \/ fa + 232 <= B0)%Z -> (fa + 232 < 2 ^ 63)%Z ->
  evt rsegs (fun ms' => exists t0' t1' t2' a1' a2' a3' a4' a5' a6' a7' t3' t4' t5' t6' m',
      ms' = MS (mkR ra sp gp tp t0' t1' t2' s0 s1 (Z_to_bv 64 l) a1' a2' a3' a4' a5' a6' a7' s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3' t4' t5' t6') F
